namespace ElswordPixel.CargoPresentationV21 {
 [Serializable] public sealed class CargoAudioContainerV21 {public string codec;public int channels,sampleRate;public double containerDurationSeconds;}
 [Serializable] public sealed class CargoAudioAssetV21 {public string id,sha256;public string[] sourceNames;public CargoFilePinV21 file;public CargoAudioContainerV21 container;}
