 [Serializable] public sealed class CargoAudioDocumentV21 {public string schema,sourceRulesSha256,sourceSoundsSha256,playbackAdapter;public CargoAudioAssetV21[] assets;public CargoStateSoundTrackV21[] stateTracks;public CargoEffectSoundTrackV21[] effectTracks;public CargoCallbackSoundV21[] callbackSounds;public bool actualAudioPlayed,actualUnityVerified;}
 [Serializable] public sealed class CargoSoundPacketV21 {public long serial,entrySerial;public int roomEpoch,loop,actorSerial,effectSerial;public string kind,npc,state,effect,eventId,sound,sourceField,sourceName;public float sourceTime,localTime,time;}
 // Original-container decoder and exact committed sound-event consumer.
 // It does not schedule an unseen animation/callback or infer native volume.
 public sealed class CargoAudioRuntimeV21:IDisposable {
  public const string SourceSoundsSha256="99fc89efec9870cebeaa1dd348d7d16530325ccae98921530c6d2014e24070be";
  readonly Dictionary<string,AudioClip> clips=new Dictionary<string,AudioClip>();readonly Dictionary<string,CargoTimedSoundV21> cues=new Dictionary<string,CargoTimedSoundV21>();readonly Dictionary<string,CargoStateSoundTrackV21> states=new Dictionary<string,CargoStateSoundTrackV21>();readonly Dictionary<string,CargoEffectSoundTrackV21> effects=new Dictionary<string,CargoEffectSoundTrackV21>();readonly HashSet<string> consumed=new HashSet<string>();readonly List<AudioSource> voices=new List<AudioSource>();readonly GameObject root;CargoAudioDocumentV21 data;int epoch,voiceCursor;long lastSerial;bool disposed;
  public int DecodedClips{get{return clips.Count;}}public int Consumed{get;private set;}public int PlaybackCalls{get;private set;}public int MutedConsumed{get;private set;}public int ActiveVoices{get{int n=0;foreach(var s in voices)if(s&&s.isPlaying)n++;return n;}}public bool AudiblePlaybackVerified{get{return false;}}public string LastError{get;private set;}
  public CargoAudioRuntimeV21(Transform parent){if(!parent)throw new ArgumentNullException("parent");root=new GameObject("Cargo exact-original audio scoped pool");root.transform.SetParent(parent,false);for(int i=0;i<16;i++){var go=new GameObject("Cargo NPC audio voice"+i);go.transform.SetParent(root.transform,false);var a=go.AddComponent<AudioSource>();a.playOnAwake=false;a.spatialBlend=0;a.loop=false;voices.Add(a);}}
  static string Sha(byte[] b){return CargoDirectorHashV21.Hash(b);}static byte[] Read(CargoFilePinV21 p){var b=File.ReadAllBytes(p.path);if(Sha(b)!=p.sha256)throw new InvalidOperationException("Changed exact source audio file: "+p.path);return b;}
  public IEnumerator Load(string path,string hash){if(disposed)throw new ObjectDisposedException("CargoAudioRuntimeV21");var raw=Read(new CargoFilePinV21{path=path,sha256=hash});data=JsonUtility.FromJson<CargoAudioDocumentV21>(System.Text.Encoding.UTF8.GetString(raw));if(data==null||data.schema!="cargo-exact-original-audio-v21"||data.sourceSoundsSha256!=SourceSoundsSha256||data.assets==null||data.assets.Length!=64||data.stateTracks==null||data.stateTracks.Length!=53||data.effectTracks==null||data.effectTracks.Length!=2||data.playbackAdapter!="existing-NPC-display-gain0.38-2D-no-source-volume-inferred-v21")throw new ArgumentException("Wrong exact Cargo audio scope");if(clips.Count>0)throw new InvalidOperationException("Use fresh scope for another audio bank");foreach(var t in data.stateTracks){states.Add(t.npc+"/"+t.state,t);foreach(var e in t.events)cues.Add(e.id,e);}foreach(var t in data.effectTracks){effects.Add(t.effect,t);foreach(var e in t.events)cues.Add(e.id,e);}
   foreach(var a in data.assets){Read(a.file);if(a.file.sha256!=a.sha256||a.container==null)throw new ArgumentException("Original audio alias pin mismatch");AudioType type=Path.GetExtension(a.file.path).Equals(".ogg",StringComparison.OrdinalIgnoreCase)?AudioType.OGGVORBIS:AudioType.WAV;using(var request=UnityWebRequestMultimedia.GetAudioClip(new Uri(a.file.path).AbsoluteUri,type)){var handler=(DownloadHandlerAudioClip)request.downloadHandler;handler.streamAudio=false;yield return request.SendWebRequest();if(request.result!=UnityWebRequest.Result.Success){LastError="Original Cargo container decode: "+a.id+" "+request.error;yield break;}AudioClip clip=DownloadHandlerAudioClip.GetContent(request);if(!clip||clip.channels!=a.container.channels||clip.frequency!=a.container.sampleRate||clip.samples<=0){if(clip)UnityEngine.Object.Destroy(clip);LastError="Original Cargo clip header mismatch: "+a.id;yield break;}clip.name=a.id;clips.Add(a.id,clip);}}
  }
  public IDictionary<string,AudioClip> GetVerifiedClips(){return new Dictionary<string,AudioClip>(clips);}
  public void ResetRoom(int roomEpoch){epoch=roomEpoch;lastSerial=0;consumed.Clear();foreach(var s in voices)if(s){s.Stop();s.clip=null;}}
  public bool Consume(CargoSoundPacketV21 p,bool muted){if(disposed||data==null||clips.Count!=64||p==null||p.roomEpoch!=epoch||p.serial<=lastSerial||p.entrySerial<=0||p.loop<0||!CargoFxFeedV21.Finite(p.time)||p.time<0)throw new ArgumentException("Invalid audio lifecycle/epoch/serial");CargoTimedSoundV21 cue;bool valid=false;if(cues.TryGetValue(p.eventId??"",out cue)){valid=cue.sound==p.sound&&cue.sourceField==p.sourceField&&cue.sourceName==p.sourceName&&Math.Abs(cue.sourceTime-p.sourceTime)<.00001&&Math.Abs(cue.candidateTime-p.localTime)<.00001;if(p.kind=="state"){CargoStateSoundTrackV21 track;valid=valid&&states.TryGetValue(p.npc+"/"+p.state,out track)&&Array.Exists(track.events,e=>e.id==p.eventId)&&p.actorSerial>0;}else if(p.kind=="effect"){CargoEffectSoundTrackV21 track;valid=valid&&effects.TryGetValue(p.effect??"",out track)&&Array.Exists(track.events,e=>e.id==p.eventId)&&CargoFxFeedV21.OwnerForEffect(p.effect)==p.npc&&p.effectSerial>0;}else valid=false;}else if(p.kind=="callback"){valid=p.npc=="NUI_WALLY_9TH_ARMOR"&&p.state=="WALLY_9TH_ARMOR_ATTACK_C"&&p.sourceName=="Wally9Armor_MissileFly.ogg"&&p.sourceField=="original-Cargo-Lua-PlaySound_LUA"&&Math.Abs(p.sourceTime-2.1f)<.00001&&Math.Abs(p.localTime-2.1f)<.00001&&Array.Exists(data.callbackSounds,s=>s.sourceName==p.sourceName&&s.sound==p.sound);}
   if(!valid)throw new ArgumentException("Same name with wrong exact Cargo sound binding");lastSerial=p.serial;string key=p.roomEpoch+"/"+p.entrySerial+"/"+p.loop+"/"+p.effectSerial+"/"+p.eventId;if(!consumed.Add(key))return false;Consumed++;if(muted){MutedConsumed++;return true;}AudioClip audio;if(!clips.TryGetValue(p.sound,out audio)||!audio)throw new InvalidOperationException("Missing original decoded clip");AudioSource voice=null;foreach(var s in voices)if(!s.isPlaying){voice=s;break;}if(!voice){voice=voices[voiceCursor++%voices.Count];voice.Stop();}voice.PlayOneShot(audio,.38f);PlaybackCalls++;return true;
  }
  public void Dispose(){if(disposed)return;disposed=true;foreach(var s in voices)if(s)s.Stop();foreach(var c in clips.Values)if(c)UnityEngine.Object.Destroy(c);clips.Clear();voices.Clear();if(root)UnityEngine.Object.Destroy(root);}
 }
 internal static class CargoDirectorHashV21 {public static string Hash(byte[] b){using(var h=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(h.ComputeHash(b)).Replace("-","").ToLowerInvariant();}}
